package com.bank.statement.service;

import com.bank.statement.dto.StatementLine;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Builds a statement. The returned list IS the per-request object graph we measure.
public class StatementService {
    private static final Logger log = Logger.getLogger(StatementService.class.getName());

    // Simulates loading N transactions into memory — the heavy request footprint.
    public List<StatementLine> generateStatement(String accountId, int lineCount) {
        log.fine(() -> "Generating statement for " + accountId + " lines=" + lineCount);
        List<StatementLine> lines = new ArrayList<>(lineCount);
        for (int i = 0; i < lineCount; i++) {
            lines.add(new StatementLine(
                    accountId,
                    "Txn-" + i + " for " + accountId,
                    new BigDecimal("1234.56")));
        }
        log.info(() -> "Statement for " + accountId + " built with " + lineCount + " lines");
        return lines;   // held in memory until response is serialized and GC'd
    }
}
