// ─── File: src/main/java/com/bank/statement/service/MemoryProfiler.java ───
package com.bank.statement.service;

import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.util.function.Supplier;
import java.util.logging.Logger;

// Heap-diff method: measure rough retained bytes per invocation.
public class MemoryProfiler {
    private static final Logger log = Logger.getLogger(MemoryProfiler.class.getName());
    private final MemoryMXBean memBean = ManagementFactory.getMemoryMXBean();

    public long usedHeap() {
        return memBean.getHeapMemoryUsage().getUsed();
    }

    // Runs the operation N times and returns rough bytes retained per run.
    public long measurePerRequest(Supplier<Object> operation, int iterations) {
        if (iterations <= 0) throw new IllegalArgumentException("iterations must be > 0");
        System.gc();                              // best-effort clean slate
        quietSleep(50);
        long before = usedHeap();

        Object sink = null;
        for (int i = 0; i < iterations; i++) {
            sink = operation.get();               // keep reference alive this loop
        }
        long after = usedHeap();
        if (sink == null) log.fine("sink was null");   // prevent dead-code elimination

        long perRequest = Math.max(0, (after - before) / iterations);
        log.info(() -> "Approx retained per request: " + perRequest + " bytes over "
                + iterations + " iterations");
        return perRequest;
    }

    private void quietSleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
