package com.bank.statement.aspect;

import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

// AOP method: sample used heap before/after each controller call for per-endpoint attribution.
@Aspect
@Component
public class MemoryProfilingAspect {
    private static final Logger log = LoggerFactory.getLogger(MemoryProfilingAspect.class);
    private final MemoryMXBean memBean = ManagementFactory.getMemoryMXBean();

    @Around("execution(* com.bank.statement.controller..*(..))")
    public Object profile(ProceedingJoinPoint pjp) throws Throwable {
        long before = memBean.getHeapMemoryUsage().getUsed();
        try {
            return pjp.proceed();
        } finally {
            long delta = memBean.getHeapMemoryUsage().getUsed() - before;
            log.info("endpoint={} heapDeltaBytes={}", pjp.getSignature().toShortString(), delta);
            // In production: meterRegistry.summary("request.heap.delta","endpoint",name).record(delta);
        }
    }
}
```

