// ─── File: src/test/java/com/bank/statement/service/MemoryProfilerTest.java ───
package com.bank.statement.service;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

class MemoryProfilerTest {

    private final MemoryProfiler profiler = new MemoryProfiler();
    private final StatementService service = new StatementService();

    @Test
    void perRequestMemory_isNonNegative() {
        long perReq = profiler.measurePerRequest(
                () -> service.generateStatement("SAV2001", 100), 200);
        assertThat(perReq).isGreaterThanOrEqualTo(0);
    }

    @Test
    void biggerStatement_costsMoreThanSmaller() {
        // Hold each result so it is retained during measurement.
        long small = retainedFor(100);
        long big = retainedFor(5000);
        assertThat(big).isGreaterThanOrEqualTo(small);
    }

    private long retainedFor(int lines) {
        MemoryProfiler p = new MemoryProfiler();
        java.util.List<Object> hold = new java.util.ArrayList<>();
        System.gc();
        long before = p.usedHeap();
        for (int i = 0; i < 50; i++) hold.add(service.generateStatement("CUR3001", lines));
        long after = p.usedHeap();
        assertThat(hold).isNotEmpty();              // keep references alive
        return Math.max(0, (after - before) / 50);
    }

    @Test
    void zeroIterations_isRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> profiler.measurePerRequest(() -> "x", 0));
    }

    @Test
    void usedHeap_isPositive() {
        assertThat(profiler.usedHeap()).isGreaterThan(0);
    }
}
